              const originPhrase = onPlayText.match(/(トラッシュから|エナゾーンから|手札以外(?:の領域)?から)[^。]*?場に出たとき/)?.[1];
              extractedTriggerCondObj = addOnPlayOriginCondition(extractedTriggerCondObj, originPhrase);
